// Playwright MCP: inject one-use grants and synthetic fixtures at runtime; never save grants.
async(page)=>{
 const contexts=[],checks=[],errors=[],check=(name,ok)=>{if(!ok)throw Error(name);checks.push(name);};
 try{
  const tabs=[];for(const link of ['__AUTHOR__','__REVIEWER__','__APPROVER__','__FINANCE_REVIEW__','__FINANCE_APPROVE__']){const ctx=await page.context().browser().newContext({viewport:{width:1440,height:1000}});contexts.push(ctx);const p=await ctx.newPage();await p.goto(link);tabs.push(p);}
  const [p,reviewer,approver,financeReview,financeApprove]=tabs;p.on('pageerror',e=>errors.push(e.message));
  async function req(tab,path,body,version){return tab.evaluate(async({path,body,version})=>{const s=await(await fetch('/dev/session')).json(),r=await fetch('/api/ops/v1'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-CSRF-Token':s.csrfToken,'Idempotency-Key':crypto.randomUUID(),...(version?{'If-Match':`"${version}"`}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error.code);return data;},{path,body,version});}
  let tariff=await req(p,'/pricing/tariffs',{name:'DEMO browser quote',owner:'DR',currency:'USD',scope:'DEMO'});
  for(const code of ['base','insurance'])tariff=await req(p,'/pricing/tariffs/'+tariff.id+'/actions/save-fee',{code,enabled:true,method:'fixed',amount:code==='base'?200:75,unit:null,includedMilli:0,stepMilli:1000,share:code==='base',scope:'DEMO',evidence:'DEMO source'},tariff.version);
  let policy=await req(p,'/pricing/tariffs/'+tariff.id+'/policy-versions',{validFrom:new Date().toISOString(),validUntil:new Date(Date.now()+3600000).toISOString(),quoteValiditySeconds:600,serviceLevels:['S2'],reason:'DEMO'},tariff.version);
  await req(reviewer,'/pricing/policy-versions/'+policy.id+'/actions/review',{reason:'DEMO independent review'},1);await req(approver,'/pricing/policy-versions/'+policy.id+'/actions/publish',{reason:'DEMO independent approval'},2);
  const {draft,input}=__FIXTURES__;draft.customerId=(await req(p,'/customers')).items[0].id;for(const side of ['pickup','delivery'])draft[side].point={lng:104.9,lat:11.5};for(const [i,k] of ['requestedPickupWindow','requestedDeliveryWindow'].entries())draft[k]={start:new Date(Date.now()+(i+1)*3600000).toISOString(),end:new Date(Date.now()+(i+2)*3600000).toISOString()};
  const area=await req(p,'/service-areas',{name:'DEMO browser quotes',type:'ALLOW',polygon:{type:'Polygon',coordinates:[[[104.8,11.4],[105,11.4],[105,11.6],[104.8,11.6],[104.8,11.4]]]},effectiveFrom:new Date().toISOString()});await req(p,'/service-areas/'+area.id+'/actions/publish',{reason:'DEMO'},1);
  const order=await req(p,'/orders',draft),op='/orders/'+order.order.id;await req(p,op+'/intake-evidence',input,1);await req(p,op+'/actions/submit',{},1);
  const quote=await req(p,op+'/quotes',{pricingPolicyVersionId:policy.id,insuranceRequested:true},2);check('real quote total and independent insurance',quote.total.amountMinor===275&&quote.calculation.shareMinor===200&&quote.calculation.insuranceMinor===75);check('quote read issued',(await req(p,'/quotes/'+quote.id)).state==='issued');
  await req(p,'/quotes/'+quote.id+'/actions/record-customer-confirmation',{customerContact:'DEMO sender',method:'MESSAGE',reference:'DEMO confirmation',confirmedAt:new Date().toISOString()},1);
  const account=(await req(p,'/finance/receiving-accounts')).items.find(a=>a.currency==='USD');
  const receipt=await req(p,op+'/prepayment-receipts',{receivingAccountId:account.id,bankReference:'DEMO-'+Date.now(),reference:'DEMO bank evidence',observedAt:new Date().toISOString(),money:{amountMinor:300,currency:'USD'}},3);
  await p.goto('http://127.0.0.1:4180/prototype/orders.html');const row=p.locator('tr').filter({has:p.locator(`[data-open="${order.order.id}"]`)});await row.waitFor();check('reported state comes from backend', (await row.innerText()).includes('收款资料待核销'));
  await req(financeReview,'/prepayment-receipts/'+receipt.id+'/actions/verify',{approve:true,reason:'DEMO independent verification'},1);
  const allocation=await req(p,op+'/prepayment-allocations',{receiptId:receipt.id,lines:quote.fees.map(f=>({feeId:f.id,amountMinor:f.money.amountMinor})),reason:'DEMO allocation'},3),ap='/prepayment-allocations/'+allocation.id;
  await req(financeReview,ap+'/actions/review',{approve:true,reason:'DEMO review'},1);await req(financeApprove,ap+'/actions/approve',{approve:true,reason:'DEMO approval'},2);check('approval alone is not paid',(await req(p,op+'/payment-admission')).allocatedMinor===0);
  await req(financeApprove,ap+'/actions/post',{reason:'DEMO posting'},3);const gate=await req(p,op+'/payment-admission');check('funds remain allocated and excess retained',gate.paymentSatisfied&&gate.allocatedMinor===275&&gate.unallocatedMinor===25&&!gate.dispatchAllowed);
  await p.reload();await row.waitFor();check('paid list no longer claims unpaid',(await row.innerText()).includes('已核销')&&!(await row.innerText()).includes('未收款'));
  const reversal=await req(p,ap+'/reversals',{reason:'DEMO incorrect allocation',reference:'DEMO investigation'},4),rp='/allocation-reversals/'+reversal.id;
  await p.reload();await row.waitFor();check('pending reversal shows disputed', (await row.innerText()).includes('有争议'));
  check('pending reversal blocks admission without changing money',!(await req(p,op+'/payment-admission')).paymentSatisfied&&(await req(p,op+'/payment-admission')).allocatedMinor===275);
  await req(financeReview,rp+'/actions/review',{approve:true,reason:'DEMO correction review'},1);await req(financeApprove,rp+'/actions/approve',{approve:true,reason:'DEMO correction approval'},2);await req(financeApprove,rp+'/actions/post',{reason:'DEMO reversal posting'},3);
  const restored=await req(p,op+'/payment-admission');check('reversal restores balances without refund',restored.confirmedMinor===300&&restored.allocatedMinor===0&&restored.unallocatedMinor===300&&restored.remainingMinor===275);check('source allocation retained as reversed',(await req(p,ap)).state==='REVERSED');
  await p.reload();await row.waitFor();check('reversed order is no longer shown as settled',(await row.innerText()).includes('收款资料待核销'));
  const corrected=await req(p,op+'/prepayment-allocations',{receiptId:receipt.id,lines:quote.fees.map(f=>({feeId:f.id,amountMinor:f.money.amountMinor})),reason:'DEMO corrected allocation'},3),np='/prepayment-allocations/'+corrected.id;
  await req(financeReview,np+'/actions/review',{approve:true,reason:'DEMO review'},1);await req(financeApprove,np+'/actions/approve',{approve:true,reason:'DEMO approval'},2);await req(financeApprove,np+'/actions/post',{reason:'DEMO posting'},3);
  await p.reload();await row.waitFor();check('new allocation settles and retains correction history',(await row.innerText()).includes('已核销')&&(await req(p,op+'/payment-admission')).reversals.length===1);
  await p.locator(`[data-open="${order.order.id}"]`).click();await p.waitForFunction(()=>document.querySelector('#edit-state').textContent.includes('已生成报价'));check('confirmed order stays readonly',await p.locator('#save-order').isDisabled());
  await p.locator('[data-step="cargo"]').focus();await p.keyboard.press('Enter');check('keyboard tabs usable',await p.locator('[data-panel="cargo"]').isVisible());await p.setViewportSize({width:390,height:844});check('narrow screen no overflow',await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await p.screenshot({path:'E:/Dr.RouteFit/services/routefit/verification/allocation-reversal/corrected-mobile.png',fullPage:true});
  await req(p,'/service-areas/'+area.id+'/actions/retire',{reason:'DEMO cleanup'},2);const after=await req(p,op+'/payment-admission');check('area retirement blocks admission and preserves money',!after.paymentSatisfied&&after.allocatedMinor===275&&after.blockers.includes('COVERAGE_CHANGED'));check('no browser JS errors',errors.length===0);
  return {checks,errors,scope:'Five synthetic local identities, real PostgreSQL prepayment and reversal HTTP calls and order-list UI projection; no finance forms or external payment'};
 }finally{for(const c of contexts)await c.close();}
}
